document.querySelectorAll('[data-toast]').forEach(function (el) { el.addEventListener('click', function () { var toast = document.createElement('div'); toast.className = 'toast'; toast.textContent = el.dataset.toast; document.body.appendChild(toast); setTimeout(function () { toast.remove() }, 1800) }) })
document.querySelectorAll('[data-demo-form]').forEach(function (form) { form.addEventListener('submit', function (event) { event.preventDefault(); var toast = document.createElement('div'); toast.className = 'toast'; toast.textContent = '原型：表单提交成功'; document.body.appendChild(toast); setTimeout(function () { toast.remove() }, 1800) }) })
document.querySelectorAll('.theme-picker button').forEach(function (button) { button.addEventListener('click', function () { document.querySelectorAll('.theme-picker button').forEach(function (item) { item.classList.remove('selected') }); button.classList.add('selected') }) })
